if(minimal.size()!=1 || minimal[0].PermissionsViewAllData || minimal[0].PermissionsModifyAllData){payload.put('fixtureError','minimal-profile-unavailable');}
else{
User runningSeed=[SELECT TimeZoneSidKey,LocaleSidKey,LanguageLocaleKey,EmailEncodingKey FROM User WHERE Id=:UserInfo.getUserId()];
User limited=new User(Alias='e17bound',Email='e17@example.invalid',EmailEncodingKey=runningSeed.EmailEncodingKey,LastName='Synthetic CRUD boundary',LanguageLocaleKey=runningSeed.LanguageLocaleKey,LocaleSidKey=runningSeed.LocaleSidKey,TimeZoneSidKey=runningSeed.TimeZoneSidKey,ProfileId=minimal[0].Id,Username='e17b.'+UserInfo.getOrganizationId()+'.'+String.valueOf(Crypto.getRandomInteger())+'@example.invalid');
List<PermissionSet> grants=[SELECT Id FROM PermissionSet WHERE Name='C185B594f708b41Limited'];
if(grants.size()!=1){payload.put('fixtureError','limited-permission-set-unavailable');}
else{
Boolean setupReady=false;
System.runAs(new User(Id=UserInfo.getUserId())){
try{insert limited;insert new PermissionSetAssignment(AssigneeId=limited.Id,PermissionSetId=grants[0].Id);setupReady=true;}
catch(DmlException setupError){payload.put('fixtureError','limited-user-setup');payload.put('fixtureExceptionType',setupError.getTypeName());if(setupError.getNumDml()>0){payload.put('fixtureDmlCode',String.valueOf(setupError.getDmlType(0)));}}
catch(Exception setupError){payload.put('fixtureError','limited-user-setup');payload.put('fixtureExceptionType',setupError.getTypeName());}
}
if(setupReady){
Boolean permissionReady=false;
System.runAs(limited){
Boolean accountRead=Account.SObjectType.getDescribe().isAccessible();Boolean accountCreate=Account.SObjectType.getDescribe().isCreateable();Boolean opportunityRead=Opportunity.SObjectType.getDescribe().isAccessible();Boolean customRead=C185B594f708b41Denied__c.SObjectType.getDescribe().isAccessible();
payload.put('p',new Map<String,Object>{'ar'=>accountRead,'accountCreate'=>accountCreate,'opr'=>opportunityRead,'customRead'=>customRead});
permissionReady=accountRead && !accountCreate && !opportunityRead && !customRead;
if(!permissionReady){payload.put('fixtureError','limited-user-permissions');}
}
if(permissionReady){payload.put('owner','actor');Account row=new Account(Name='Synthetic CRUD boundary',OwnerId=limited.Id);System.runAs(limited){payload.put('es',true);try{insert row;payload.put('rc',row.Id==null?0:1);payload.put('os',0);if(row.Id==null){payload.put('fixtureError','insert-effect-not-fired');}payload.put('succeeded',true);}catch(Exception measuredError){payload.put('succeeded',false);payload.put('et',measuredError.getTypeName());String measuredMessage=measuredError.getMessage();if(measuredMessage.contains('UNKNOWN_EXCEPTION')){payload.put('platformFaultCode','UNKNOWN_EXCEPTION');}else if(measuredMessage.contains('UNABLE_TO_LOCK_ROW')){payload.put('platformFaultCode','UNABLE_TO_LOCK_ROW');}else if(measuredMessage.contains('Internal Salesforce Error')){payload.put('platformFaultCode','INTERNAL_SALESFORCE_ERROR');}else if(measuredMessage.contains('An unexpected error occurred') && measuredMessage.contains('ErrorId')){payload.put('platformFaultCode','SALESFORCE_GACK');}payload.put('em',measuredMessage);}}if(row.Id!=null && payload.get('succeeded')==true){Id insertedId=row.Id;Id actorOwner=limited.Id;Integer verified=[SELECT COUNT() FROM Account WHERE Id=:insertedId AND OwnerId=:actorOwner];payload.put('sc',verified);if(verified!=1){payload.put('fixtureError','insert-owner-not-verified');}}}
}
}
}
}catch(Exception harnessError){payload.put('fixtureError','boundary-harness-exception');payload.put('fixtureExceptionType',harnessError.getTypeName());}String serialized=JSON.serialize(payload);if(serialized.length()>550){serialized=JSON.serialize(new Map<String,Object>{'fixtureError'=>'marker-payload-too-large','payloadLength'=>serialized.length(),'owner'=>payload.get('owner'),'platformFaultCode'=>payload.get('platformFaultCode')});}System.assert(false,'C126_RESULT|C185BD_001|'+serialized);}}

